class AddNotesDialogController{constructor($mdDialog,toastrService,DispatchData,id,fieldName,title,job){this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService;this.isLoading=false;this.id=id;this.title=title;this.job=job;this._fieldName=fieldName;this.note=""}async submit(note){try{this.isLoading=true;if(this._fieldName==="Notes"){await this.addJobNote(this.job.id,note,FirstName,this.job.preBook,this.job.bulkJob)}else{const callData={call:"updateDetailField",field:this._fieldName,value:note,jobID:this.job.id};await this.updateJobDetail(this.job.bulkJob,callData.jobID,callData.field,callData.value,this.job.charge,FirstName,ContactID,this.job.preBook)}this.toastrService.showSuccessToast("Added Note To Job");this.$mdDialog.hide()}catch(error){this.toastrService.showErrorToast(error.message)}finally{this.isLoading=false}}async addJobNote(id,note,firstName,preBook,bulkJob){if(bulkJob){await this.DispatchData.addBulkJobNote(id,note,firstName,preBook)}else{await this.DispatchData.addNote(id,note,firstName,preBook)}}async updateJobDetail(bulkJob,jobID,field,value,charge,firstName,contactID,preBook){if(bulkJob){await this.DispatchData.updateBulkJobDetail(jobID,field,value,charge,firstName,contactID)}else{await this.DispatchData.updateJobDetail(jobID,field,value,charge,firstName,contactID,preBook)}}cancel(){this.$mdDialog.cancel()}}